use filmcraft_geom::Vec2;use filmcraft_project::{Project,ItemId,MediaRef,Interpolation,ParamValue,Keyframe};use filmcraft_time::{Tick,FrameRate};use filmcraft_media::{SharedSource,generators::GeneratorSource};use filmcraft_render::{render_sequence,RenderOptions};use serde_json::{Value,json};use std::sync::Arc;
fn main(){let input:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();const T:i64=254016000000;let mut cases=vec![];let defs:Vec<_>=filmcraft_project::effect_defs().iter().filter(|d|matches!(d.id,"magnify")).collect();assert_eq!(defs.len(),1);
for definition in defs{for shape in 0..2{for mode in 0..5{for profile in 0..6{let mut effect=definition.instance();let control="center";
effect.params.get_mut("shape").unwrap().value=ParamValue::Choice(shape);effect.params.get_mut("mode").unwrap().value=ParamValue::Choice(mode);
let (lo,hi)=match profile{0=>(Vec2::new(f64::NAN,f64::NAN),Vec2::new(f64::NAN,f64::NAN)),1=>(Vec2::new(1.25,6.75),Vec2::new(1.25,6.75)),2=>(Vec2::new(-2.25,7.75),Vec2::new(8.125,-1.5)),3=>(Vec2::new(-2.25,7.75),Vec2::new(f64::NAN,f64::NAN)),4=>(Vec2::new(f64::NAN,7.75),Vec2::new(8.125,f64::NAN)),_=>(Vec2::new(-2.25,7.75),Vec2::new(f64::NAN,f64::NAN))};
let param=effect.params.get_mut(control).unwrap();param.value=ParamValue::Vec2(lo);if profile>=2{let mut first=Keyframe::new(Tick(T),ParamValue::Vec2(lo));if profile==5{first.interp=Interpolation::Hold;}param.keyframes=vec![first,Keyframe::new(Tick(2*T),ParamValue::Vec2(hi))];}
for (name,value) in [("size",2.5),("feather",0.75),("magnification",200.)]{effect.params.get_mut(name).unwrap().value=ParamValue::Float(value);}
let mut doc=input["cases"][0]["document"].clone();let media=&mut doc["project"]["items"]["1"]["kind"]["Media"];media["media"]=json!({"Generator":{"Demo":"Plasma"}});media["info"]["video"]["width"]=json!(8);media["info"]["video"]["height"]=json!(8);
let seq=&mut doc["project"]["items"]["6"]["kind"]["Sequence"];seq["settings"]["width"]=json!(16);seq["settings"]["height"]=json!(8);seq["caption_tracks"]=json!([]);let mut track=seq["video_tracks"][0].clone();track["enabled"]=json!(true);track["transitions"]=json!([]);let mut clip=track["items"][0].clone();clip["item"]=json!(1);clip["start"]=json!(0);clip["duration"]=json!(10*T);clip["source_in"]=json!(0);clip["speed"]=json!(1.);clip["reverse"]=json!(false);clip["frame_hold"]=Value::Null;clip["effects"]=json!([effect]);track["items"]=json!([clip]);seq["video_tracks"]=json!([track]);let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();let provider=|id:ItemId|{let(_,media,_)=p.resolve_media(id)?;let MediaRef::Generator(generator)=&media.media else{return None};Some(Arc::new(GeneratorSource::new(generator.clone(),8,8,FrameRate::new(24,1),Tick(100*T)))as SharedSource)};
for at in [0,T,T+1,3*T/2,2*T,3*T]{for scale in [1.,0.5]{let out=render_sequence(&p,ItemId(6),Tick(at),RenderOptions{scale,working_output:true,..Default::default()},&provider);cases.push(json!({"document":doc,"sequence":6,"at":at,"effect":definition.id,"profile":profile,"shape":shape,"mode":mode,"scale":scale,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}
}}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","definitions":1,"cases":cases}));}
